// Kräver miljövariabeln ALARM_WEBHOOK_TOKEN i Node-RED.
// Använd en lång, slumpmässig token. Lägg aldrig token i GitHub.
const headers = msg.req?.headers || {};
const supplied = headers["x-alarm-token"];
const expected = env.get("ALARM_WEBHOOK_TOKEN");

function answer(code, result) {
    return {
        req: msg.req,
        res: msg.res,
        statusCode: code,
        headers: {
            "Content-Type": "application/json; charset=utf-8",
            "Cache-Control": "no-store"
        },
        payload: JSON.stringify(result)
    };
}

if (typeof expected !== "string" || expected.length < 24) {
    node.warn("ALARM_WEBHOOK_TOKEN saknas eller är för kort.");
    return [null, answer(503, { ok: false })];
}

if (typeof supplied !== "string" || supplied !== expected) {
    node.warn("Obehörigt anrop till alarm-webhook.");
    return [null, answer(403, { ok: false })];
}

const now = Date.now();
const last = context.get("lastAlarmAt") || 0;
if (now - last < 30000) {
    return [null, answer(429, { ok: false, error: "Vänta 30 sekunder." })];
}
context.set("lastAlarmAt", now);

node.status({ fill: "green", shape: "dot", text: "Larmkommando skickat " + new Date().toLocaleTimeString("sv-SE") });

// Sänder till din befintliga ESP32-S3 via MQTT.
// Den andra utgången kvitterar endast att Node-RED tog emot kommandot.
return [
    { topic: "kamera/larm", payload: "1", qos: 0, retain: false },
    answer(202, { ok: true })
];
